func filterFruits(query string) []string {
	if query == "" {
		return nil
	}
	var out []string
	q := strings.ToLower(query)
	for _, f := range searchFruits {
		if strings.Contains(strings.ToLower(f), q) {
			out = append(out, f)
		}
	}
	return out
}

