func wireFileUploader(document *html.Document) {
	input := document.GetElementByID("uploader-input").AsInput()
	input.AddEventListener("change", js.FuncOf(func(this js.Value, args []js.Value) any {
		go func() {
			files := input.Files()
			if len(files) == 0 {
				document.GetElementByID("file-result").SetTextContent("no file")
				return
			}
			f := browser.WrapFile(files[0])
			text, err := f.ReadAsText()
			if err != nil {
				document.GetElementByID("file-result").SetTextContent("error: " + err.Error())
				return
			}
			document.GetElementByID("file-result").SetTextContent(
				fmt.Sprintf("name=%s size=%d text=%s", f.Name(), f.Size(), text))
		}()
		return nil
	}))
}

func wireContextMenu(document *html.Document, st *state, render func()) {
	target := document.GetElementByID("contextmenu-target")
	target.OnContextMenu(func(x, y float64) {
		st.contextMenuOpen = true
		st.contextMenuX = x
		st.contextMenuY = y
		render()
	})
}

func main() {
	document := browser.Document()
	container := document.GetElementByID("app")

	st := &state{
		accordionOpen:    map[int]bool{0: true},
		radioSelected:    "b",
		dateValue:        "2024-01-15",
		colorValue:       "#336699",
		sliderValue:      30,
		chipLabels:       []string{"go", "wasm", "xango"},
		dropdownSelected: []string{"go"},
		paginationPage:   5,
		collabRole:       components.CollabEditor,
	}

	var root *domrt.Root
	var render func()
	render = func() {
		node := App(st, render)
		if root == nil {
			root = domrt.Mount(container.Element, node)
		} else {
			root.Update(node)
		}
	}
	render()

	wireFileUploader(document)
	wireContextMenu(document, st, render)
	wireOTPFocusAdvance(document)

	select {} // keep the wasm program alive for every component's event callbacks
}
